// Package command holds the survey module's write-side use cases.
package command

import (
	"context"

	"github.com/zenstar13/survey-prototype/internal/platform/clock"
	"github.com/zenstar13/survey-prototype/internal/platform/id"
	"github.com/zenstar13/survey-prototype/internal/survey/domain"
)

// QuestionInput is the authoring input for one question. Option IDs are
// generated by the handler.
type QuestionInput struct {
	Prompt   string
	Type     string
	Required bool
	Options  []string
}

// CreateDraftSurvey creates a new survey in draft state.
type CreateDraftSurvey struct {
	SurveyID    string
	Title       string
	Description string
	Questions   []QuestionInput
}

// ReviseDraftSurvey replaces the full content of a draft survey.
type ReviseDraftSurvey struct {
	SurveyID    string
	Title       string
	Description string
	Questions   []QuestionInput
}

type PublishSurvey struct{ SurveyID string }

type CloseSurvey struct{ SurveyID string }

type CreateDraftSurveyHandler struct {
	repo  domain.Repository
	ids   id.Generator
	clock clock.Clock
}

func NewCreateDraftSurveyHandler(repo domain.Repository, ids id.Generator, clk clock.Clock) CreateDraftSurveyHandler {
	return CreateDraftSurveyHandler{repo: repo, ids: ids, clock: clk}
}

func (h CreateDraftSurveyHandler) Handle(ctx context.Context, cmd CreateDraftSurvey) error {
	s, err := domain.NewDraft(cmd.SurveyID, cmd.Title, cmd.Description, toSpecs(cmd.Questions, h.ids), h.clock.Now())
	if err != nil {
		return err
	}
	return h.repo.Add(ctx, s)
}

type ReviseDraftSurveyHandler struct {
	repo  domain.Repository
	ids   id.Generator
	clock clock.Clock
}

func NewReviseDraftSurveyHandler(repo domain.Repository, ids id.Generator, clk clock.Clock) ReviseDraftSurveyHandler {
	return ReviseDraftSurveyHandler{repo: repo, ids: ids, clock: clk}
}

func (h ReviseDraftSurveyHandler) Handle(ctx context.Context, cmd ReviseDraftSurvey) error {
	specs := toSpecs(cmd.Questions, h.ids)
	return h.repo.Update(ctx, cmd.SurveyID, func(s *domain.Survey) error {
		return s.ReviseDraft(cmd.Title, cmd.Description, specs, h.clock.Now())
	})
}

type PublishSurveyHandler struct {
	repo  domain.Repository
	clock clock.Clock
}

func NewPublishSurveyHandler(repo domain.Repository, clk clock.Clock) PublishSurveyHandler {
	return PublishSurveyHandler{repo: repo, clock: clk}
}

func (h PublishSurveyHandler) Handle(ctx context.Context, cmd PublishSurvey) error {
	return h.repo.Update(ctx, cmd.SurveyID, func(s *domain.Survey) error {
		return s.Publish(h.clock.Now())
	})
}

type CloseSurveyHandler struct {
	repo  domain.Repository
	clock clock.Clock
}

func NewCloseSurveyHandler(repo domain.Repository, clk clock.Clock) CloseSurveyHandler {
	return CloseSurveyHandler{repo: repo, clock: clk}
}

func (h CloseSurveyHandler) Handle(ctx context.Context, cmd CloseSurvey) error {
	return h.repo.Update(ctx, cmd.SurveyID, func(s *domain.Survey) error {
		return s.Close(h.clock.Now())
	})
}

func toSpecs(in []QuestionInput, ids id.Generator) []domain.QuestionSpec {
	out := make([]domain.QuestionSpec, 0, len(in))
	for _, q := range in {
		opts := make([]domain.OptionSpec, 0, len(q.Options))
		for _, label := range q.Options {
			opts = append(opts, domain.OptionSpec{ID: ids.NewID(), Label: label})
		}
		out = append(out, domain.QuestionSpec{
			ID: ids.NewID(), Prompt: q.Prompt, Type: domain.QuestionType(q.Type), Required: q.Required, Options: opts,
		})
	}
	return out
}
